// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address newOwner) public {
        // keep params in the admissible domain: a fresh non-zero recipient
        vm.assume(newOwner != address(0));

        // initially owner() == address(0), so address(0) is the current owner;
        // current owner transfers ownership to the fuzzed recipient
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // the designated new owner must now be able to renounce ownership
        vm.prank(newOwner);
        bool ok;
        try c.renounceOwnership() { ok = true; } catch { ok = false; }

        // general rule: after a successful ownership transfer to newOwner,
        // newOwner's owner-only operations succeed, and renouncing yields owner()==0
        assertTrue(ok && c.owner() == address(0));
    }
}
